1. //! platform-bridge — typed Rust access to the Python `sonic_platform` plugin via PyO3.
2. //!
3. //! # Why this exists
4. //! The Rust rewrite of xcvrd must talk to the SAME transceiver plant the Python
5. //! daemon talks to: the `sonic_platform` plugin that speaks gRPC to `xcvr-emu`.
6. //! Its `Sfp` subclasses `SfpOptoeBase`, so the entire CMIS/SFF decode stack
7. //! (`get_transceiver_info`, `get_transceiver_dom_real_value`,
8. //! `get_transceiver_status`, lpmode/reset, …) already exists in Python, built on
9. //! three primitive hooks (`read_eeprom`/`write_eeprom`/`get_presence`).
10. //!
11. //! Rather than re-implement CMIS decode in Rust, we keep a THICK boundary: this
12. //! bridge embeds CPython, imports the real plugin, and exposes its high-level
13. //! results to Rust. The translation agents write only the daemon LOGIC on top of
14. //! this; they never reimplement the platform. Complex return values
15. //! (transceiver info/DOM/status dicts) are marshalled as `serde_json::Value` so
16. //! the surface stays stable as milestones add fields; scalars come back typed.
17. //!
18. //! # Runtime requirements
19. //! Embeds libpython3.13 (`auto-initialize`). At run time the process must find
20. //! `libpython3.13.so.1.0` and an importable `sonic_platform` — both true inside
21. //! pmon. Constructing [`Platform`] performs the emulator `List()` RPC, and the
22. //! `get_transceiver_*` calls perform EEPROM reads over gRPC, so `xcvr-emu` must
23. //! be running (it is, in pmon).
24. 
25. use std::collections::BTreeMap;
26. 
27. use pyo3::prelude::*;
28. use pyo3::types::{PyBytes, PyDict};
29. use serde_json::Value;
30. use thiserror::Error;
31. 
32. /// Errors surfaced by the bridge. Python failures include the formatted
33. /// traceback so import/attribute problems on the DUT are debuggable from logs.
34. #[derive(Error, Debug)]
35. pub enum BridgeError {
36.     #[error("python error: {0}")]
37.     Py(String),
38.     #[error("json marshalling error: {0}")]
39.     Json(String),
40.     #[error("bridge error: {0}")]
41.     Other(String),
42. }
43. 
44. impl From<PyErr> for BridgeError {
45.     fn from(e: PyErr) -> Self {
46.         Python::with_gil(|py| {
47.             let tb = e
48.                 .traceback_bound(py)
49.                 .and_then(|t| t.format().ok())
50.                 .unwrap_or_default();
51.             BridgeError::Py(format!("{e}\n{tb}"))
52.         })
53.     }
54. }
55. 
56. pub type Result<T> = std::result::Result<T, BridgeError>;
57. 
58. /// Crate version, for smoke logging.
59. pub fn bridge_version() -> &'static str {
60.     env!("CARGO_PKG_VERSION")
61. }
62. 
63. /// One transceiver change-event poll: `chassis.get_change_event(timeout)` returns
64. /// `(status, {'sfp': {port: code}, 'sfp_error': {port: code}})`. Keys are physical
65. /// port strings; values are xcvrd event codes (`"1"` insert, `"0"` remove, other =
66. /// SfpBase error bitmap).
67. #[derive(Debug, Clone, Default)]
68. pub struct ChangeEvent {
69.     pub status: bool,
70.     pub sfp: BTreeMap<String, String>,
71.     pub sfp_error: BTreeMap<String, String>,
72. }
73. 
74. /// `json.dumps(obj, default=str)` -> `serde_json::Value`. Robust to arbitrary
75. /// nesting and future fields; anything not natively JSON-able is str()'d.
76. fn py_to_json(py: Python<'_>, obj: &Bound<'_, PyAny>) -> Result<Value> {
77.     if obj.is_none() {
78.         return Ok(Value::Null);
79.     }
80.     let json = py.import_bound("json")?;
81.     let builtins = py.import_bound("builtins")?;
82.     let kwargs = PyDict::new_bound(py);
83.     kwargs.set_item("default", builtins.getattr("str")?)?;
84.     let dumped = json.call_method("dumps", (obj,), Some(&kwargs))?;
85.     let s: String = dumped.extract()?;
86.     serde_json::from_str(&s).map_err(|e| BridgeError::Json(e.to_string()))
87. }
88. 
89. /// Pull a `{str: str}` map out of a JSON object value (missing/!object -> empty).
90. fn json_str_map(v: Option<&Value>) -> BTreeMap<String, String> {
91.     let mut out = BTreeMap::new();
92.     if let Some(Value::Object(map)) = v {
93.         for (k, val) in map {
94.             let s = match val {
95.                 Value::String(s) => s.clone(),
96.                 other => other.to_string(),
97.             };
98.             out.insert(k.clone(), s);
99.         }
100.     }
101.     out
102. }
103. 
104. /// The transceiver plant: `sonic_platform.platform.Platform().get_chassis()`.
105. ///
106. /// Cheap to clone-free share across threads is NOT provided; construct once and
107. /// hand out [`Sfp`] handles. Each call re-acquires the GIL.
108. pub struct Platform {
109.     chassis: Py<PyAny>,
110. }
111. 
112. impl Platform {
113.     /// Import the plugin and build the chassis. Triggers the emulator `List()`
114.     /// RPC (falls back to `XCVR_EMU_NUM_SFPS` placeholders if the emulator is not
115.     /// up yet, exactly like the Python daemon at start-up).
116.     pub fn new() -> Result<Self> {
117.         Python::with_gil(|py| {
118.             let module = py.import_bound("sonic_platform.platform")?;
119.             let platform = module.getattr("Platform")?.call0()?;
120.             let chassis = platform.call_method0("get_chassis")?;
121.             Ok(Platform {
122.                 chassis: chassis.unbind(),
123.             })
124.         })
125.     }
126. 
127.     /// Number of SFP slots the chassis discovered.
128.     pub fn num_sfps(&self) -> Result<usize> {
129.         Python::with_gil(|py| {
130.             let n = self.chassis.bind(py).call_method0("get_num_sfps")?;
131.             Ok(n.extract()?)
132.         })
133.     }
134. 
135.     /// Handle to the SFP at `index` (0-based, == emulator module index). Returns
136.     /// an error if the chassis has no SFP there.
137.     pub fn sfp(&self, index: usize) -> Result<Sfp> {
138.         Python::with_gil(|py| {
139.             let obj = self.chassis.bind(py).call_method1("get_sfp", (index,))?;
140.             if obj.is_none() {
141.                 return Err(BridgeError::Other(format!("no sfp at index {index}")));
142.             }
143.             Ok(Sfp {
144.                 obj: obj.unbind(),
145.                 index,
146.             })
147.         })
148.     }
149. 
150.     /// Poll for transceiver change events. `timeout_ms == 0` blocks up to the
151.     /// plugin's poll interval; otherwise blocks up to `timeout_ms`, returning
152.     /// early on the first change.
153.     pub fn get_change_event(&self, timeout_ms: u64) -> Result<ChangeEvent> {
154.         Python::with_gil(|py| {
155.             let res = self
156.                 .chassis
157.                 .bind(py)
158.                 .call_method1("get_change_event", (timeout_ms,))?;
159.             let (status, events): (bool, Bound<'_, PyAny>) = res.extract()?;
160.             let ev = py_to_json(py, &events)?;
161.             Ok(ChangeEvent {
162.                 status,
163.                 sfp: json_str_map(ev.get("sfp")),
164.                 sfp_error: json_str_map(ev.get("sfp_error")),
165.             })
166.         })
167.     }
168. }
169. 
170. /// A single transceiver slot. All getters re-acquire the GIL and call straight
171. /// through to the Python `Sfp` (i.e. `SfpOptoeBase` + the emulator overrides).
172. pub struct Sfp {
173.     obj: Py<PyAny>,
174.     index: usize,
175. }
176. 
177. impl Sfp {
178.     /// 0-based physical index this handle wraps.
179.     pub fn index(&self) -> usize {
180.         self.index
181.     }
182. 
183.     fn call_bool(&self, method: &str) -> Result<bool> {
184.         Python::with_gil(|py| Ok(self.obj.bind(py).call_method0(method)?.extract()?))
185.     }
186. 
187.     /// Is a module physically present (emulator `GetInfo().present`).
188.     pub fn get_presence(&self) -> Result<bool> {
189.         self.call_bool("get_presence")
190.     }
191. 
192.     /// Whether the slot is field-replaceable (always true on the emulator).
193.     pub fn is_replaceable(&self) -> Result<bool> {
194.         self.call_bool("is_replaceable")
195.     }
196. 
197.     /// Whether the module is held in reset (always false on the emulator).
198.     pub fn get_reset_status(&self) -> Result<bool> {
199.         self.call_bool("get_reset_status")
200.     }
201. 
202.     /// The `sfp_type` attribute (e.g. `"QSFP_DD"`).
203.     pub fn sfp_type(&self) -> Result<String> {
204.         Python::with_gil(|py| Ok(self.obj.bind(py).getattr("sfp_type")?.extract()?))
205.     }
206. 
207.     /// Human-readable error description, if any.
208.     pub fn get_error_description(&self) -> Result<Option<String>> {
209.         Python::with_gil(|py| {
210.             let r = self.obj.bind(py).call_method0("get_error_description")?;
211.             if r.is_none() {
212.                 Ok(None)
213.             } else {
214.                 Ok(Some(r.extract()?))
215.             }
216.         })
217.     }
218. 
219.     /// Full CMIS/SFF identity dict (`TRANSCEIVER_INFO` source). [M1]
220.     pub fn get_transceiver_info(&self) -> Result<Value> {
221.         self.call_json("get_transceiver_info", ())
222.     }
223. 
224.     /// Live DOM sensor readings (`TRANSCEIVER_DOM_SENSOR` source). [M2]
225.     pub fn get_transceiver_dom_real_value(&self) -> Result<Value> {
226.         self.call_json("get_transceiver_dom_real_value", ())
227.     }
228. 
229.     /// Module/datapath status (`TRANSCEIVER_STATUS` source, incl. cmis_state). [M3]
230.     pub fn get_transceiver_status(&self) -> Result<Value> {
231.         self.call_json("get_transceiver_status", ())
232.     }
233. 
234.     /// DOM thresholds (`TRANSCEIVER_DOM_THRESHOLD` source).
235.     pub fn get_transceiver_threshold_info(&self) -> Result<Value> {
236.         self.call_json("get_transceiver_threshold_info", ())
237.     }
238. 
239.     /// Low-power mode state. [M4]
240.     pub fn get_lpmode(&self) -> Result<bool> {
241.         self.call_bool("get_lpmode")
242.     }
243. 
244.     /// Drive low-power mode on/off. [M4]
245.     pub fn set_lpmode(&self, on: bool) -> Result<bool> {
246.         Python::with_gil(|py| Ok(self.obj.bind(py).call_method1("set_lpmode", (on,))?.extract()?))
247.     }
248. 
249.     /// Momentary CMIS software reset. [M4]
250.     pub fn reset(&self) -> Result<bool> {
251.         self.call_bool("reset")
252.     }
253. 
254.     /// Read `num_bytes` of EEPROM at the optoe-linear `offset`. `None` on RPC
255.     /// failure (matches the plugin's `read_eeprom` contract).
256.     pub fn read_eeprom(&self, offset: usize, num_bytes: usize) -> Result<Option<Vec<u8>>> {
257.         Python::with_gil(|py| {
258.             let r = self
259.                 .obj
260.                 .bind(py)
261.                 .call_method1("read_eeprom", (offset, num_bytes))?;
262.             if r.is_none() {
263.                 return Ok(None);
264.             }
265.             // read_eeprom returns a bytearray; normalise to bytes then to Vec<u8>.
266.             let as_bytes = py.import_bound("builtins")?.getattr("bytes")?.call1((r,))?;
267.             Ok(Some(as_bytes.extract()?))
268.         })
269.     }
270. 
271.     /// Write `data` to EEPROM at the optoe-linear `offset`. Returns the plugin's
272.     /// success flag.
273.     pub fn write_eeprom(&self, offset: usize, data: &[u8]) -> Result<bool> {
274.         Python::with_gil(|py| {
275.             let buf = PyBytes::new_bound(py, data);
276.             let ok = self
277.                 .obj
278.                 .bind(py)
279.                 .call_method1("write_eeprom", (offset, data.len(), buf))?;
280.             Ok(ok.extract()?)
281.         })
282.     }
283. 
284.     /// Escape hatch: call any no-arg Python `Sfp` method and marshal its result as
285.     /// JSON. Lets the daemon reach methods not yet given a typed wrapper without a
286.     /// bridge change.
287.     pub fn call_json(&self, method: &str, args: impl IntoPy<Py<pyo3::types::PyTuple>>) -> Result<Value> {
288.         Python::with_gil(|py| {
289.             let r = self.obj.bind(py).call_method1(method, args)?;
290.             py_to_json(py, &r)
291.         })
292.     }
293. }
