         Python::with_gil(|py| {
             let res = self
                 .chassis
                 .bind(py)
                 .call_method1("get_change_event", (timeout_ms,))?;
             let (status, events): (bool, Bound<'_, PyAny>) = res.extract()?;
             let ev = py_to_json(py, &events)?;
             Ok(ChangeEvent {
                 status,
                 sfp: json_str_map(ev.get("sfp")),
                 sfp_error: json_str_map(ev.get("sfp_error")),
             })
         })
     }
 }

