95. /// Publish (or clear) one port's identity + SW status from live HAL state.
96. fn sync_port(platform: &Platform, state: &DbConnector, phys: usize, port: &str) -> Result<(), Box<dyn Error>> {
97.     let sfp = platform.sfp(phys)?;
98.     let info_key = format!("{INFO_TABLE}|{port}");
99.     let sw_key = format!("{STATUS_SW_TABLE}|{port}");
100. 
101.     if sfp.get_presence()? {
102.         let info = sfp.get_transceiver_info()?;
103.         if let Some(obj) = info.as_object() {
104.             for (field, value) in obj {
105.                 if let Some(s) = stringify(value) {
106.                     state.hset(&info_key, field, &CxxString::from(s.as_str()))?;
107.                 }
108.             }
109.         }
110.         let replaceable = sfp.is_replaceable().unwrap_or(false);
111.         state.hset(&info_key, "is_replaceable", &CxxString::from(pybool(replaceable)))?;
112.         state.hset(&sw_key, "status", &CxxString::from("1"))?;
113.         state.hset(&sw_key, "cmis_state", &CxxString::from("READY"))?;
114.     } else {
115.         state.del(&info_key)?;
116.         state.hset(&sw_key, "status", &CxxString::from("0"))?;
117.     }
118.     Ok(())
119. }
120. 
121. /// Python-style bool rendering, matching `str(bool)` the reference daemon writes.
122. fn pybool(b: bool) -> &'static str {
123.     if b {
124.         "True"
125.     } else {
126.         "False"
127.     }
128. }
129. 
130. /// Render a `get_transceiver_info()` JSON value as the STATE_DB field string the
131. /// reference daemon writes via `str(value)`. Strings are trimmed of trailing NUL
132. /// padding (and trailing spaces); JSON nulls are skipped.
133. fn stringify(v: &serde_json::Value) -> Option<String> {
134.     use serde_json::Value;
135.     match v {
136.         Value::Null => None,
137.         Value::String(s) => Some(s.trim_end_matches('\0').trim_end().to_string()),
138.         Value::Bool(b) => Some(pybool(*b).to_string()),
139.         Value::Number(n) => Some(n.to_string()),
140.         other => Some(other.to_string()),
